    n, m = len(nums1), len(nums2)
    best = 0
    for i in range(n):
        for j in range(m):
            length = 0
            while i + length < n and j + length < m and nums1[i + length] == nums2[j + length]:
                length += 1                                                 # extend while both arrays keep matching from this pair of starts
            best = max(best, length)
