        int n = nums1.length, m = nums2.length;
        int best = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int length = 0;
                while (i + length < n && j + length < m && nums1[i + length] == nums2[j + length]) {
