def find_length(nums1, nums2):
    n, m = len(nums1), len(nums2)
    dp = [[0] * (m + 1) for _ in range(n + 1)]                             # dp[i][j] = length of the matching streak ending at nums1[i-1], nums2[j-1]
    best = 0
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if nums1[i - 1] == nums2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1                            # extend the diagonal streak from the previous pair of positions
                best = max(best, dp[i][j])
            # else dp[i][j] stays 0: a mismatch breaks the streak completely
    return best


if __name__ == "__main__":
    print(find_length([1, 2, 3, 2, 1], [3, 2, 1, 4, 7]))

