                    dp[i][j] = dp[i - 1][j - 1] + 1;                                // extend the diagonal streak from the previous pair of positions
                    best = Math.max(best, dp[i][j]);
                }
                // else dp[i][j] stays 0 (default): a mismatch breaks the streak completely
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.findLength(new int[]{1, 2, 3, 2, 1}, new int[]{3, 2, 1, 4, 7}));
    }
}

